package com.shopstream.catalog.config;

import io.lettuce.core.ReadFrom;
import org.springframework.boot.data.redis.autoconfigure.*;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class RedisReadConfig {

    @Bean
    LettuceClientConfigurationBuilderCustomizer readFromReplicas() {
        return builder -> builder.readFrom(ReadFrom.REPLICA_PREFERRED);
    }
}

package com.shopstream.config;

import java.time.Duration;

import io.lettuce.core.cluster.ClusterClientOptions;
import io.lettuce.core.cluster.ClusterTopologyRefreshOptions;
import org.springframework.boot.data.redis.autoconfigure.*;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class RedisClusterConfig {

    @Bean
    LettuceClientConfigurationBuilderCustomizer clusterRefresh() {
        ClusterTopologyRefreshOptions refresh = ClusterTopologyRefreshOptions.builder()
                .enablePeriodicRefresh(Duration.ofSeconds(30))
                .enableAllAdaptiveRefreshTriggers()
                .build();
        ClusterClientOptions options = ClusterClientOptions.builder()
                .topologyRefreshOptions(refresh)
                .build();
        return builder -> builder.clientOptions(options);
    }
}
